  if (!Number.isInteger(a) || !Number.isInteger(b)) return 'a and b must be whole numbers.';
  if (a < 1 || b > 1000) return 'a and b must lie between 1 and 1000.';
  if (a > b) return 'a must not be larger than b.';
  return null;
}

