function numberCount(a, b) {
  let count = 0;

  for (let x = a; x <= b; x++) {
    const seen = new Set();
    let value = x;
    let unique = true;
    while (value > 0) {
      const digit = value % 10;
      if (seen.has(digit)) {
        unique = false;
        break;
      }
      seen.add(digit);
      value = Math.floor(value / 10);
    }
    if (unique) {
      count++;
    }
  }
  return count;
}

