function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    return [int(1, 60), int(940, 1000)];
  }
  const shape = int(0, 2);
  const a = shape === 0 ? int(1, 30) : shape === 1 ? int(90, 130) : int(1, 1000);
  const b = Math.min(1000, a + int(0, shape === 2 ? 40 : 25));
